 9	namespace Application\API\Parameters\Type;
10	
11	use Application\API\Parameters\Validation\ParamValidationInterface;
12	
13	/**
14	 * Clearable string API parameter with three-state resolution semantics.
15	 *
16	 * Unlike {@see StringParameter}, this type distinguishes between an absent
17	 * parameter and a present-but-empty parameter, enabling Update-style API
18	 * methods to explicitly clear optional metadata fields:
19	 *
20	 * - **Absent** (key not in `$_REQUEST`) → `null`
21	 * - **Present but empty** (empty string or whitespace-only after trim) → `''`
22	 * - **Present with value** (non-empty after trim) → trimmed string
23	 *
24	 * Reading `$_REQUEST` directly via `array_key_exists()` is intentional:
25	 * the framework's `RequestParam::get()` discards empty strings before the
26	 * parameter type ever sees them, which would collapse the absent/empty
27	 * distinction that this type relies on.
28	 *
29	 * @package API
30	 * @subpackage Parameters
31	 */
32	class ClearableStringParameter extends StringParameter
33	{
34	    public function getTypeLabel(): string
35	    {
36	        return t('Clearable string');
37	    }
38	
39	    /**
40	     * Resolves the parameter value from `$_REQUEST` with three-state semantics.
41	     *
42	     * - Key absent → `null`
43	     * - Key present, value empty or whitespace-only (after trim) → `''`
44	     * - Key present, value non-empty (after trim) → trimmed string
45	     * - Numeric values → string representation of the number
46	     * - Non-string, non-numeric values → `null` (with a warning)
47	     *
48	     * @return string|null
49	     */
50	    protected function resolveValue(): ?string
51	    {
52	        if(!array_key_exists($this->getName(), $_REQUEST)) {
53	            return null;
54	        }
55	
56	        $raw = $_REQUEST[$this->getName()];
57	
58	        if(is_numeric($raw)) {
59	            return trim((string)$raw);
60	        }
61	
62	        if(!is_string($raw)) {
63	            $this->result->makeWarning(
64	                sprintf('The value must be a string, [%s] given.', gettype($raw)),
65	                ParamValidationInterface::VALIDATION_INVALID_VALUE_TYPE
66	            );
67	            return null;
68	        }
69	
70	        $trimmed = trim($raw);
71	
72	        if($trimmed === '') {
73	            return '';
74	        }
75	
76	        return $trimmed;
77	    }
78	}

