11	/**
12	 * Tests for {@see ClearableStringParameter}.
13	 *
14	 * Covers all three resolution states (absent, empty/whitespace, value),
15	 * edge cases (numeric values, non-string values), hasValue() behaviour,
16	 * and setMaxLength() integration.
17	 */
18	final class ClearableStringParameterTest extends APITestCase
19	{
20	    // region: Resolution states
21	
22	    public function test_absentKey_returnsNull() : void
23	    {
24	        // Key is not in $_REQUEST at all
25	        $param = new ClearableStringParameter('foo', 'Param Label');
26	
27	        $this->assertNull($param->getValue());
28	        $this->assertResultValidWithNoMessages($param->getValidationResults());
29	    }
30	
31	    public function test_emptyStringPresent_returnsEmptyString() : void
32	    {
33	        $_REQUEST['foo'] = '';
34	
35	        $param = new ClearableStringParameter('foo', 'Param Label');
36	
37	        $this->assertSame('', $param->getValue());
38	        $this->assertResultValidWithNoMessages($param->getValidationResults());
39	    }
40	
41	    public function test_whitespaceOnlyPresent_returnsEmptyString() : void
42	    {
43	        $_REQUEST['foo'] = '   ';
44	
45	        $param = new ClearableStringParameter('foo', 'Param Label');
46	
47	        $this->assertSame('', $param->getValue());
48	        $this->assertResultValidWithNoMessages($param->getValidationResults());
49	    }
50	
51	    public function test_validString_returnsTrimmedString() : void
52	    {
53	        $_REQUEST['foo'] = 'hello';
54	
55	        $param = new ClearableStringParameter('foo', 'Param Label');
56	
57	        $this->assertSame('hello', $param->getValue());
58	        $this->assertResultValidWithNoMessages($param->getValidationResults());
59	    }
60	
61	    public function test_validStringWithLeadingTrailingWhitespace_returnsTrimmedString() : void
62	    {
63	        $_REQUEST['foo'] = '  hello world  ';
64	
65	        $param = new ClearableStringParameter('foo', 'Param Label');
66	
67	        $this->assertSame('hello world', $param->getValue());
68	        $this->assertResultValidWithNoMessages($param->getValidationResults());
69	    }
70	
71	    // endregion
72	
73	    // region: Numeric values
74	
75	    public function test_integerValue_returnsStringRepresentation() : void
76	    {
77	        $_REQUEST['foo'] = 42;
78	
79	        $param = new ClearableStringParameter('foo', 'Param Label');
80	
81	        $this->assertSame('42', $param->getValue());
82	        $this->assertResultValidWithNoMessages($param->getValidationResults());
83	    }
84	
85	    public function test_floatValue_returnsStringRepresentation() : void
86	    {
87	        $_REQUEST['foo'] = 3.14;
88	
89	        $param = new ClearableStringParameter('foo', 'Param Label');
90	
91	        $this->assertSame('3.14', $param->getValue());
92	        $this->assertResultValidWithNoMessages($param->getValidationResults());
93	    }
94	
95	    public function test_numericStringValue_returnsString() : void
96	    {
97	        $_REQUEST['foo'] = '123';
98	
99	        $param = new ClearableStringParameter('foo', 'Param Label');

100	
101	        $this->assertSame('123', $param->getValue());
102	        $this->assertResultValidWithNoMessages($param->getValidationResults());
103	    }
104	
105	    // endregion
106	
107	    // region: Non-string values
108	
109	    public function test_arrayValue_returnsNullWithWarning() : void
110	    {
111	        $_REQUEST['foo'] = array('not', 'a', 'string');
112	
113	        $param = new ClearableStringParameter('foo', 'Param Label');
114	
115	        $this->assertNull($param->getValue());
