120	    public function test_nullValue_distinguishedFromAbsent_returnsNull() : void
121	    {
122	        // Key is present in $_REQUEST but value is null.
123	        // array_key_exists returns true for null values, so this is treated
124	        // as "present with non-string value" → null with warning.
125	        $_REQUEST['foo'] = null;
126	
127	        $param = new ClearableStringParameter('foo', 'Param Label');
128	
129	        // null is not numeric and not a string, so it produces a warning.
130	        // The result should still be marked with invalid value type.
131	        $this->assertNull($param->getValue());
132	        $this->assertResultHasInvalidValueType($param->getValidationResults());
133	    }
134	
135	    // endregion
136	
137	    // region: hasValue() behaviour
138	
139	    public function test_hasValue_absentKey_returnsFalse() : void
140	    {
141	        $param = new ClearableStringParameter('foo', 'Param Label');
142	
143	        $this->assertFalse($param->hasValue());
144	    }
145	
146	    public function test_hasValue_emptyStringPresent_returnsTrue() : void
147	    {
