175	    // region: setMaxLength() integration
176	
177	    public function test_setMaxLength_valueBelowLimit_passes() : void
178	    {
179	        $_REQUEST['foo'] = 'hi';
180	
181	        $param = new ClearableStringParameter('foo', 'Param Label');
182	        $param->setMaxLength(5);
183	
184	        $this->assertSame('hi', $param->getValue());
185	        $this->assertResultValidWithNoMessages($param->getValidationResults());
186	    }
187	
188	    public function test_setMaxLength_valueExceedsLimit_fails() : void
189	    {
190	        $_REQUEST['foo'] = 'toolong';
191	
192	        $param = new ClearableStringParameter('foo', 'Param Label');
193	        $param->setMaxLength(5);
194	
195	        $this->assertNull($param->getValue());
196	        $this->assertResultInvalid($param->getValidationResults());
197	        $this->assertResultHasCode($param->getValidationResults(), ParamValidationInterface::VALIDATION_MAX_LENGTH_EXCEEDED);
198	    }

199	
200	    public function test_setMaxLength_emptyStringPresent_notCapped() : void
201	    {
202	        // An empty string (clearable value) should not be rejected by max-length
203	        // validation — MaxLengthValidation skips empty strings.
204	        $_REQUEST['foo'] = '';
205	
206	        $param = new ClearableStringParameter('foo', 'Param Label');
207	        $param->setMaxLength(3);
208	
209	        $this->assertSame('', $param->getValue());
210	        $this->assertResultValidWithNoMessages($param->getValidationResults());
211	    }
212	
213	    public function test_setMaxLength_absentKey_notCapped() : void
214	    {
215	        // An absent key resolves to null; max-length validation skips null.
216	        $param = new ClearableStringParameter('foo', 'Param Label');
217	        $param->setMaxLength(3);
218	
219	        $this->assertNull($param->getValue());
220	        $this->assertResultValidWithNoMessages($param->getValidationResults());
221	    }
222	
223	    public function test_setMaxLength_returnsThisForFluentChaining() : void
224	    {
225	        $param = new ClearableStringParameter('foo', 'Param Label');
226	        $result = $param->setMaxLength(10);
227	
228	        $this->assertSame($param, $result);
229	    }
230	
231	    // endregion
232	
233	    // region: Type label
234	
235	    public function test_getTypeLabel_returnsClearableString() : void
236	    {
237	        $param = new ClearableStringParameter('foo', 'Param Label');
238	
239	        $this->assertStringContainsString('learable', $param->getTypeLabel());
240	    }
241	
242	    // endregion
243	}

